 * @param {string} missingProperty - The missing property name
 * @param {string[]} candidates - Available property names
 * @returns {string|null} The closest matching property name or null
 */
function findClosestMatch(missingProperty, candidates) {
  if (candidates.length === 0) {
    return null;
  }

  let bestDistance = Infinity;
  let bestCandidates = [];

